#include "mrp.h"

void read_centers(Model *model) { Strings lines=read_lines("workcenters.csv"); for (int i=1;i<lines.count;i++) { Strings fields=split(lines.data[i],','); char **f=fields.data,*message=NULL; int64_t efficiency=integer(f[2]); if (find_center(model,f[0])>=0) message=format("duplicate center %s",f[0]); else if (efficiency<50 || efficiency>150) message=format("bad efficiency %" PRId64,efficiency); if (message) { record_error(model,"workcenters.csv",i+1,message); continue; } int index=model->center_count++; WorkCenter *center=&model->centers[index]; strcpy(center->id,f[0]); strcpy(center->description,f[3]); center->minutes=integer(f[1]); center->efficiency=efficiency; center->available=center->minutes*efficiency/100; int position=index; while (position>0 && strcmp(model->centers[model->center_order[position-1]].id,center->id)>0) { model->center_order[position]=model->center_order[position-1]; position--; } model->center_order[position]=index; } }
void read_routings(Model *model) { Strings lines=read_lines("routings.csv"); for (int i=1;i<lines.count;i++) { Strings fields=split(lines.data[i],','); char **f=fields.data,*message=NULL; int item=find_item(model,f[0]),center=find_center(model,f[2]),number=(int)integer(f[1]); int64_t run=integer(f[4]); if (item<0) message=format("unknown item %s",f[0]); else if (center<0) message=format("unknown center %s",f[2]); else if (!model->items[item].child_count) message=format("purchased item %s",f[0]); else if (run<1) message=format("bad run time %" PRId64,run); if (!message) for (int j=0;j<model->items[item].operation_count;j++) if (model->operations[model->items[item].operations[j]].number==number) { message=format("duplicate %s operation %d",f[0],number); break; } if (message) { record_error(model,"routings.csv",i+1,message); continue; } int index=model->operation_count++; model->operations[index]=(Operation){item,number,center,integer(f[3]),run}; Item *record=&model->items[item]; int position=record->operation_count++; while (position>0 && model->operations[record->operations[position-1]].number>number) { record->operations[position]=record->operations[position-1]; position--; } record->operations[position]=index; } }
int operation_week(int receipt,int lead,int index,int count) { int week=receipt-lead+index*lead/count; return week<1 ? 1 : week; }
void level_loads(const int64_t *loads,int64_t available,int horizon,int64_t *leveled) { int64_t carry=0; for (int week=horizon;week>=2;week--) { int64_t total=loads[week]+carry; leveled[week]=total<available ? total : available; carry=total-leveled[week]; } leveled[1]=loads[1]+carry; }
